namespace UniversityCourseCatalog.Models;

public record Department(string Id, string Name, string Description);

public record Instructor(string Name, string Title, string Bio);

public record Course(
    string Id,
    string DepartmentId,
    string Code,
    string Title,
    string Description,
    int Credits,
    string Schedule,
    string Location,
    Instructor Instructor,
    bool IsFeatured = false);

public class EnrollmentRequest
{
    public string StudentName { get; set; } = "";
    public string StudentId { get; set; } = "";
    public string CourseId { get; set; } = "";
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Course> _courses;
    private readonly List<EnrollmentRequest> _enrollments = new();

    public CatalogService()
    {
        _departments = new List<Department>
        {
            new("cs", "Computer Science", "Study of computation, algorithms, and information systems."),
            new("math", "Mathematics", "Pure and applied mathematics including statistics and data analysis."),
            new("eng", "English", "Literature, writing, and language studies."),
            new("phys", "Physics", "Study of matter, energy, and the fundamental forces of nature."),
            new("hist", "History", "Exploration of past events, civilizations, and cultural developments."),
            new("bio", "Biology", "Study of living organisms, genetics, and ecosystems.")
        };

        _courses = new List<Course>
        {
            // Computer Science
            new("cs101", "cs", "CS 101", "Introduction to Programming",
                "Learn the fundamentals of programming using Python. Topics include variables, control flow, functions, data structures, and object-oriented programming. No prior experience required.",
                3, "Mon/Wed/Fri 9:00–9:50 AM", "Science Hall 201",
                new Instructor("Dr. Sarah Chen", "Associate Professor", "Dr. Chen has 12 years of experience teaching introductory CS. She earned her Ph.D. from MIT and has published extensively on CS education pedagogy."),
                IsFeatured: true),
            new("cs201", "cs", "CS 201", "Data Structures & Algorithms",
                "Study fundamental data structures (arrays, linked lists, trees, graphs, hash tables) and algorithm design techniques. Includes analysis of time and space complexity.",
                4, "Tue/Thu 10:00–11:15 AM", "Science Hall 305",
                new Instructor("Dr. James Park", "Professor", "Dr. Park specializes in algorithm design and has authored two widely-used textbooks on data structures. He received the University Teaching Excellence Award in 2023.")),
            new("cs310", "cs", "CS 310", "Database Systems",
                "Comprehensive study of relational database design, SQL, normalization, transaction management, and an introduction to NoSQL databases.",
                3, "Mon/Wed 2:00–3:15 PM", "Tech Building 110",
                new Instructor("Dr. Maria Lopez", "Assistant Professor", "Dr. Lopez worked as a database architect at Oracle for 8 years before joining academia. Her research focuses on distributed database optimization.")),
            new("cs450", "cs", "CS 450", "Machine Learning",
                "Introduction to machine learning concepts including supervised and unsupervised learning, neural networks, and model evaluation. Requires strong background in linear algebra and statistics.",
                4, "Tue/Thu 1:00–2:15 PM", "Tech Building 220",
                new Instructor("Dr. Sarah Chen", "Associate Professor", "Dr. Chen's research interests span machine learning and artificial intelligence, with a focus on explainable AI systems."),
                IsFeatured: true),

            // Mathematics
            new("math101", "math", "MATH 101", "Calculus I",
                "Limits, continuity, derivatives, and integrals of single-variable functions. Applications to physics and engineering problems.",
                4, "Mon/Wed/Fri 10:00–10:50 AM", "Math Building 100",
                new Instructor("Dr. Robert Kim", "Professor", "Dr. Kim has been teaching calculus for over 20 years. He is known for making abstract concepts accessible through real-world applications."),
                IsFeatured: true),
            new("math201", "math", "MATH 201", "Linear Algebra",
                "Vector spaces, linear transformations, matrices, determinants, eigenvalues, and eigenvectors. Essential for advanced STEM coursework.",
                3, "Tue/Thu 9:00–10:15 AM", "Math Building 202",
                new Instructor("Dr. Emily Zhang", "Associate Professor", "Dr. Zhang's research is in algebraic geometry. She brings a unique perspective connecting linear algebra to modern mathematical research.")),
            new("math301", "math", "MATH 301", "Probability & Statistics",
                "Probability theory, random variables, distributions, hypothesis testing, regression analysis, and Bayesian methods.",
                3, "Mon/Wed/Fri 1:00–1:50 PM", "Math Building 100",
                new Instructor("Dr. Robert Kim", "Professor", "Dr. Kim also teaches statistics, drawing on his consulting experience with pharmaceutical companies on clinical trial design.")),

            // English
            new("eng101", "eng", "ENG 101", "Composition & Rhetoric",
                "Develop critical reading and academic writing skills. Emphasis on thesis development, argumentation, research methods, and MLA citation.",
                3, "Mon/Wed/Fri 11:00–11:50 AM", "Humanities 301",
                new Instructor("Prof. David Miller", "Senior Lecturer", "Prof. Miller has published three books on writing pedagogy and has been recognized nationally for his innovative approaches to teaching composition.")),
            new("eng220", "eng", "ENG 220", "American Literature",
                "Survey of American literary works from the colonial period to the present. Authors include Hawthorne, Twain, Fitzgerald, Morrison, and contemporary voices.",
                3, "Tue/Thu 2:00–3:15 PM", "Humanities 205",
                new Instructor("Dr. Angela Brooks", "Associate Professor", "Dr. Brooks specializes in 20th-century American fiction and has published numerous articles on the Harlem Renaissance literary movement."),
                IsFeatured: true),
            new("eng350", "eng", "ENG 350", "Creative Writing Workshop",
                "Workshop-based course focusing on fiction and poetry. Students produce a portfolio of original work and provide peer feedback.",
                3, "Wed 6:00–8:30 PM", "Humanities 105",
                new Instructor("Prof. Lisa Tanaka", "Visiting Writer", "Prof. Tanaka is an award-winning novelist whose latest book was longlisted for the National Book Award. She brings real-world publishing experience to the workshop.")),

            // Physics
            new("phys101", "phys", "PHYS 101", "General Physics I",
                "Mechanics, thermodynamics, and waves. Includes weekly lab sessions with hands-on experiments and data analysis.",
                4, "Mon/Wed/Fri 8:00–8:50 AM, Lab: Fri 2:00–4:50 PM", "Science Hall 101",
                new Instructor("Dr. Alan Foster", "Professor", "Dr. Foster is an experimental physicist whose research in condensed matter physics has been funded by NSF grants for over a decade.")),
            new("phys301", "phys", "PHYS 301", "Quantum Mechanics",
                "Introduction to quantum theory: wave-particle duality, Schrödinger equation, quantum states, operators, and measurement. Prerequisite: PHYS 201 and MATH 201.",
                4, "Tue/Thu 11:00 AM–12:15 PM", "Science Hall 401",
                new Instructor("Dr. Priya Sharma", "Associate Professor", "Dr. Sharma's research on quantum computing bridges theoretical physics and computer science. She has published in Nature Physics and Physical Review Letters.")),

            // History
            new("hist101", "hist", "HIST 101", "World History to 1500",
                "Survey of major civilizations, empires, and cultural exchanges from prehistory through the late medieval period.",
                3, "Tue/Thu 9:00–10:15 AM", "Liberal Arts 200",
                new Instructor("Dr. Michael Torres", "Professor", "Dr. Torres is a medievalist whose fieldwork in archaeological sites across Europe has informed his teaching and research on ancient trade networks.")),
            new("hist250", "hist", "HIST 250", "The Modern Middle East",
                "Political, social, and cultural history of the Middle East from the Ottoman Empire to the present day.",
                3, "Mon/Wed 3:30–4:45 PM", "Liberal Arts 310",
                new Instructor("Dr. Fatima Al-Rashid", "Assistant Professor", "Dr. Al-Rashid is a specialist in modern Middle Eastern history with a focus on social movements and democratization processes.")),

            // Biology
            new("bio101", "bio", "BIO 101", "Introduction to Biology",
                "Fundamentals of cell biology, genetics, evolution, and ecology. Lab sessions include microscopy, DNA extraction, and ecological surveys.",
                4, "Mon/Wed/Fri 10:00–10:50 AM, Lab: Tue 2:00–4:50 PM", "Life Sciences 100",
                new Instructor("Dr. Karen White", "Professor", "Dr. White has received multiple teaching awards and is known for her engaging lecture style. Her research focuses on marine ecology and conservation biology."),
                IsFeatured: true),
            new("bio310", "bio", "BIO 310", "Genetics & Molecular Biology",
                "Gene structure and expression, DNA replication, transcription, translation, and recombinant DNA technology. Lab-intensive.",
                4, "Tue/Thu 10:00–11:15 AM, Lab: Thu 2:00–4:50 PM", "Life Sciences 300",
                new Instructor("Dr. Nathan Rivera", "Associate Professor", "Dr. Rivera spent 5 years at the NIH before joining the faculty. His lab investigates the genetic basis of inherited diseases."))
        };
    }

    public IReadOnlyList<Department> GetDepartments() => _departments;

    public Department? GetDepartment(string id) =>
        _departments.FirstOrDefault(d => d.Id.Equals(id, StringComparison.OrdinalIgnoreCase));

    public IReadOnlyList<Course> GetAllCourses() => _courses;

    public IReadOnlyList<Course> GetFeaturedCourses() =>
        _courses.Where(c => c.IsFeatured).ToList();

    public IReadOnlyList<Course> SearchCourses(string? searchTerm, string? departmentId)
    {
        var query = _courses.AsEnumerable();

        if (!string.IsNullOrWhiteSpace(departmentId))
            query = query.Where(c => c.DepartmentId.Equals(departmentId, StringComparison.OrdinalIgnoreCase));

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.Trim();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Code.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Instructor.Name.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }

    public Course? GetCourse(string id) =>
        _courses.FirstOrDefault(c => c.Id.Equals(id, StringComparison.OrdinalIgnoreCase));

    public IReadOnlyList<Course> GetCoursesByDepartment(string departmentId) =>
        _courses.Where(c => c.DepartmentId.Equals(departmentId, StringComparison.OrdinalIgnoreCase)).ToList();

    public void SubmitEnrollment(EnrollmentRequest request)
    {
        _enrollments.Add(request);
    }
}

