@page "/courses"
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject CatalogService Catalog

<PageTitle>Browse Courses</PageTitle>

<h1>Browse Courses</h1>

<form method="get" action="courses" class="row g-3 mb-4">
    <div class="col-md-6">
        <label for="search" class="form-label">Search</label>
        <input type="text" class="form-control" id="search" name="search" value="@Search"
               placeholder="Search by title, code, description, or instructor..." />
    </div>
    <div class="col-md-4">
        <label for="department" class="form-label">Department</label>
        <select class="form-select" id="department" name="department">
            <option value="">All Departments</option>
            @foreach (var dept in Catalog.GetDepartments())
            {
                <option value="@dept.Id" selected="@(Department == dept.Id)">@dept.Name</option>
            }
        </select>
    </div>
    <div class="col-md-2 d-flex align-items-end">
        <button type="submit" class="btn btn-primary w-100">Filter</button>
    </div>
</form>

@{
    var courses = Catalog.SearchCourses(Search, Department);
    var deptName = !string.IsNullOrEmpty(Department) ? Catalog.GetDepartment(Department)?.Name : null;
}

@if (!string.IsNullOrEmpty(deptName))
{
    <h5 class="mb-3">Showing courses in <strong>@deptName</strong></h5>
}

@if (courses.Count == 0)
{
    <div class="alert alert-info">No courses found matching your criteria.</div>
}
else
{
    <div class="table-responsive">
        <table class="table table-striped table-hover">
            <thead>
                <tr>
                    <th>Code</th>
                    <th>Title</th>
                    <th>Credits</th>
                    <th>Schedule</th>
                    <th>Instructor</th>
                    <th></th>
                </tr>
            </thead>
            <tbody>
                @foreach (var course in courses)
                {
                    <tr>
                        <td>@course.Code</td>
                        <td>@course.Title</td>
                        <td>@course.Credits</td>
                        <td>@course.Schedule</td>
                        <td>@course.Instructor.Name</td>
                        <td><a href="courses/@course.Id" class="btn btn-outline-primary btn-sm">Details</a></td>
                    </tr>
                }
            </tbody>
        </table>
    </div>
    <p class="text-muted">@courses.Count course(s) found</p>
}

@code {
    [SupplyParameterFromQuery] public string? Search { get; set; }
    [SupplyParameterFromQuery] public string? Department { get; set; }
}

@page "/courses/{CourseId}"
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject CatalogService Catalog

@{
    var course = Catalog.GetCourse(CourseId ?? "");
    var department = course != null ? Catalog.GetDepartment(course.DepartmentId) : null;
}

@if (course is null)
{
    <PageTitle>Course Not Found</PageTitle>
    <h1>Course Not Found</h1>
    <p>The requested course could not be found.</p>
    <a href="courses" class="btn btn-primary">Back to Course List</a>
}
else
{
    <PageTitle>@course.Code — @course.Title</PageTitle>

    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="courses">Courses</a></li>
            @if (department is not null)
            {
                <li class="breadcrumb-item"><a href="courses?department=@department.Id">@department.Name</a></li>
            }
            <li class="breadcrumb-item active" aria-current="page">@course.Code</li>
        </ol>
    </nav>

    <h1>@course.Code: @course.Title</h1>

    <div class="row mt-4">
        <div class="col-lg-8">
            <h4>Description</h4>
            <p>@course.Description</p>

            <h4 class="mt-4">Course Details</h4>
            <table class="table">
                <tbody>
                    <tr><th style="width:150px">Credits</th><td>@course.Credits</td></tr>
                    <tr><th>Schedule</th><td>@course.Schedule</td></tr>
                    <tr><th>Location</th><td>@course.Location</td></tr>
                    @if (department is not null)
                    {
                        <tr><th>Department</th><td>@department.Name</td></tr>
                    }
                </tbody>
            </table>
        </div>

        <div class="col-lg-4">
            <div class="card">
                <div class="card-body">
                    <h5 class="card-title">Instructor</h5>
                    <h6 class="card-subtitle mb-2 text-muted">@course.Instructor.Name</h6>
                    <p class="card-text"><em>@course.Instructor.Title</em></p>
                    <p class="card-text">@course.Instructor.Bio</p>
                </div>
            </div>

            <div class="mt-3">
                <a href="enroll?course=@course.Id" class="btn btn-success w-100">Request Enrollment</a>
            </div>
        </div>
    </div>
}

@code {
    [Parameter] public string? CourseId { get; set; }
}

@page "/enroll"
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject CatalogService Catalog

<PageTitle>Enrollment Request</PageTitle>

<h1>Enrollment Request</h1>
<p>Fill out the form below to request enrollment in a course.</p>

<div class="row">
    <div class="col-lg-6">
        <form method="post" action="enroll/confirm">
            <AntiforgeryToken />

            <div class="mb-3">
                <label for="studentName" class="form-label">Full Name</label>
                <input type="text" class="form-control" id="studentName" name="StudentName" required />
            </div>

            <div class="mb-3">
                <label for="studentId" class="form-label">Student ID</label>
                <input type="text" class="form-control" id="studentId" name="StudentId"
                       placeholder="e.g., S12345678" required />
            </div>

            <div class="mb-3">
                <label for="courseId" class="form-label">Course</label>
                <select class="form-select" id="courseId" name="CourseId" required>
                    <option value="">— Select a course —</option>
                    @foreach (var course in Catalog.GetAllCourses())
                    {
                        <option value="@course.Id" selected="@(PreselectedCourse == course.Id)">
                            @course.Code — @course.Title (@course.Credits cr.)
                        </option>
                    }
                </select>
            </div>

            <button type="submit" class="btn btn-success">Submit Enrollment Request</button>
        </form>
    </div>
</div>

@code {
    [SupplyParameterFromQuery(Name = "course")]
    public string? PreselectedCourse { get; set; }
}

@page "/enroll/confirm"
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject CatalogService Catalog

<PageTitle>Enrollment Submitted</PageTitle>

@if (_course is null)
{
    <h1>Invalid Request</h1>
    <p>The enrollment request was invalid. Please <a href="enroll">try again</a>.</p>
}
else
{
