}

@page "/courses/{CourseId}"
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject CatalogService Catalog

@{
    var course = Catalog.GetCourse(CourseId ?? "");
    var department = course != null ? Catalog.GetDepartment(course.DepartmentId) : null;
}

@if (course is null)
{
    <PageTitle>Course Not Found</PageTitle>
    <h1>Course Not Found</h1>
    <p>The requested course could not be found.</p>
    <a href="courses" class="btn btn-primary">Back to Course List</a>
}
else
{
    <PageTitle>@course.Code — @course.Title</PageTitle>

    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="courses">Courses</a></li>
            @if (department is not null)
            {
                <li class="breadcrumb-item"><a href="courses?department=@department.Id">@department.Name</a></li>
            }
            <li class="breadcrumb-item active" aria-current="page">@course.Code</li>
        </ol>
    </nav>

    <h1>@course.Code: @course.Title</h1>

    <div class="row mt-4">
        <div class="col-lg-8">
            <h4>Description</h4>
            <p>@course.Description</p>

            <h4 class="mt-4">Course Details</h4>
            <table class="table">
                <tbody>
                    <tr><th style="width:150px">Credits</th><td>@course.Credits</td></tr>
                    <tr><th>Schedule</th><td>@course.Schedule</td></tr>
                    <tr><th>Location</th><td>@course.Location</td></tr>
                    @if (department is not null)
                    {
                        <tr><th>Department</th><td>@department.Name</td></tr>
                    }
                </tbody>
            </table>
        </div>

        <div class="col-lg-4">
            <div class="card">
                <div class="card-body">
                    <h5 class="card-title">Instructor</h5>
                    <h6 class="card-subtitle mb-2 text-muted">@course.Instructor.Name</h6>
                    <p class="card-text"><em>@course.Instructor.Title</em></p>
                    <p class="card-text">@course.Instructor.Bio</p>
                </div>
            </div>

            <div class="mt-3">
                <a href="enroll?course=@course.Id" class="btn btn-success w-100">Request Enrollment</a>
            </div>
        </div>
    </div>
}

@code {
    [Parameter] public string? CourseId { get; set; }
}

@page "/enroll"
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
