@page "/enroll"
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject CatalogService Catalog

<PageTitle>Enrollment Request</PageTitle>

@if (_submitted && _course is not null)
{
    <h1>Enrollment Request Submitted</h1>
    <div class="alert alert-success">
        <strong>Thank you, @Model!.StudentName!</strong> Your enrollment request has been received.
    </div>

    <div class="card" style="max-width: 500px;">
        <div class="card-body">
            <h5 class="card-title">Request Summary</h5>
            <table class="table table-sm mb-0">
                <tbody>
                    <tr><th>Student Name</th><td>@Model!.StudentName</td></tr>
                    <tr><th>Student ID</th><td>@Model!.StudentId</td></tr>
                    <tr><th>Course</th><td>@_course.Code — @_course.Title</td></tr>
                    <tr><th>Credits</th><td>@_course.Credits</td></tr>
                </tbody>
            </table>
        </div>
    </div>

    <div class="mt-3">
        <a href="courses" class="btn btn-primary">Browse More Courses</a>
        <a href="enroll" class="btn btn-outline-secondary ms-2">Submit Another Request</a>
    </div>
}
else
{
    <h1>Enrollment Request</h1>
    <p>Fill out the form below to request enrollment in a course.</p>

    <div class="row">
        <div class="col-lg-6">
            <form method="post" @formname="enrollment" @onsubmit="HandleSubmit">
                <AntiforgeryToken />

                <div class="mb-3">
                    <label for="studentName" class="form-label">Full Name</label>
                    <input type="text" class="form-control" id="studentName"
                           name="Model.StudentName" value="@Model?.StudentName" required />
                </div>

                <div class="mb-3">
                    <label for="studentId" class="form-label">Student ID</label>
                    <input type="text" class="form-control" id="studentId"
                           name="Model.StudentId" value="@Model?.StudentId"
                           placeholder="e.g., S12345678" required />
                </div>

                <div class="mb-3">
                    <label for="courseId" class="form-label">Course</label>
                    <select class="form-select" id="courseId" name="Model.CourseId" required>
                        <option value="">— Select a course —</option>
                        @foreach (var course in Catalog.GetAllCourses())
                        {
                            <option value="@course.Id" selected="@(SelectedCourseId == course.Id)">
                                @course.Code — @course.Title (@course.Credits cr.)
                            </option>
                        }
                    </select>
                </div>

                <button type="submit" class="btn btn-success">Submit Enrollment Request</button>
            </form>
        </div>
    </div>
}

@code {
    [SupplyParameterFromQuery(Name = "course")]
    public string? PreselectedCourse { get; set; }

    [SupplyParameterFromForm]
    public EnrollmentRequest? Model { get; set; }

    private bool _submitted;
    private Course? _course;

    private string? SelectedCourseId => Model?.CourseId ?? PreselectedCourse;

    protected override void OnInitialized()
    {
        Model ??= new EnrollmentRequest();
    }

    private void HandleSubmit()
    {
        if (Model is not null &&
            !string.IsNullOrWhiteSpace(Model.StudentName) &&
            !string.IsNullOrWhiteSpace(Model.StudentId) &&
            !string.IsNullOrWhiteSpace(Model.CourseId))
        {
            _course = Catalog.GetCourse(Model.CourseId);
            if (_course is not null)
            {
                Catalog.SubmitEnrollment(Model);
                _submitted = true;
            }
        }
    }
}

